-- Additional spoken lines; the game controls its emote animation and text.
local _, addon = ...
-- Fully qualified addon table paths stay editable in RPTextStudio.
addon.localeData.frFR.generalTexts.INCOMING = { gruppe = { "Attention ! De la visite, et pas des plus amicales !", "Ils approchent. Préparez-vous." }, ziel = { "%s: Ils approchent. Préparez-vous.", "%s: Attention ! De la visite, et pas des plus amicales !" } }
addon.localeData.frFR.generalTexts.INSULT = { gruppe = { "Certaines paroles ne méritent pas de réponse polie.", "Ton arrogance dépasse ta sagesse." }, ziel = { "%s: Ton arrogance dépasse ta sagesse.", "%s: Certaines paroles ne méritent pas de réponse polie." } }
addon.localeData.frFR.generalTexts.INTRODUCE = { gruppe = { "Permettez-moi de me présenter.", "Un bon commencement commence par un nom." }, ziel = { "%s: Un bon commencement commence par un nom.", "%s: Permettez-moi de me présenter." } }
addon.localeData.frFR.generalTexts.JK = { gruppe = { "Je plaisante ! Rangez donc les armes.", "Un peu d'humour peut sembler dangereux." }, ziel = { "%s: Un peu d'humour peut sembler dangereux.", "%s: Je plaisante ! Rangez donc les armes." } }
addon.localeData.frFR.generalTexts.KISS = { gruppe = { "Un baiser en dit parfois plus qu'un discours.", "La vie est trop courte pour oublier la tendresse." }, ziel = { "%s: La vie est trop courte pour oublier la tendresse.", "%s: Un baiser en dit parfois plus qu'un discours." } }
addon.localeData.frFR.generalTexts.KNUCKLES = { gruppe = { "Ces mains sont prêtes. Et les tiennes ?", "Espérons que ce sera un combat loyal." }, ziel = { "%s: Espérons que ce sera un combat loyal.", "%s: Ces mains sont prêtes. Et les tiennes ?" } }
addon.localeData.frFR.generalTexts.LAVISH = { gruppe = { "Les compliments ne sont pas faits pour être rationnés.", "Cette entrée mérite un hommage royal." }, ziel = { "%s: Cette entrée mérite un hommage royal.", "%s: Les compliments ne sont pas faits pour être rationnés." } }
addon.localeData.frFR.generalTexts.LICK = { gruppe = { "Le goût est... inhabituel.", "J'aurais peut-être dû demander avant." }, ziel = { "%s: J'aurais peut-être dû demander avant.", "%s: Le goût est... inhabituel." } }
addon.localeData.frFR.generalTexts.LISTEN = { gruppe = { "Un instant. J'entends quelque chose.", "Les voix discrètes racontent souvent davantage." }, ziel = { "%s: Les voix discrètes racontent souvent davantage.", "%s: Un instant. J'entends quelque chose." } }
addon.localeData.frFR.generalTexts.LOST = { gruppe = { "Ce détour ne figurait pas sur ma carte.", "Nous ne sommes pas perdus, seulement ailleurs que prévu." }, ziel = { "%s: Nous ne sommes pas perdus, seulement ailleurs que prévu.", "%s: Ce détour ne figurait pas sur ma carte." } }
addon.localeData.frFR.generalTexts.MASSAGE = { gruppe = { "Une longue marche exige son prix.", "Ces épaules ont grand besoin de repos." }, ziel = { "%s: Ces épaules ont grand besoin de repos.", "%s: Une longue marche exige son prix." } }
addon.localeData.frFR.generalTexts.MOAN = { gruppe = { "C'était moins agréable que prévu.", "On a bien le droit de se plaindre parfois, non ?" }, ziel = { "%s: On a bien le droit de se plaindre parfois, non ?", "%s: C'était moins agréable que prévu." } }
addon.localeData.frFR.generalTexts.MOCK = { gruppe = { "Vraiment impressionnant. Presque.", "Tu devrais peut-être t'entraîner encore un peu." }, ziel = { "%s: Tu devrais peut-être t'entraîner encore un peu.", "%s: Vraiment impressionnant. Presque." } }
addon.localeData.frFR.generalTexts.MOON = { gruppe = { "Certains ne l'oublieront pas de sitôt.", "J'appelle cela une salutation originale." }, ziel = { "%s: J'appelle cela une salutation originale.", "%s: Certains ne l'oublieront pas de sitôt." } }
addon.localeData.frFR.generalTexts.MOURN = { gruppe = { "Une vie dépasse largement sa dernière heure.", "Puisse le souvenir durer plus longtemps que le chagrin." }, ziel = { "%s: Puisse le souvenir durer plus longtemps que le chagrin.", "%s: Une vie dépasse largement sa dernière heure." } }
addon.localeData.frFR.generalTexts.NO = { gruppe = { "Non. Et c'est définitif.", "Toutes les propositions ne méritent pas notre accord." }, ziel = { "%s: Toutes les propositions ne méritent pas notre accord.", "%s: Non. Et c'est définitif." } }
addon.localeData.frFR.generalTexts.NOSEPICK = { gruppe = { "Certaines recherches devraient rester privées.", "Ce n'était pas très distingué." }, ziel = { "%s: Ce n'était pas très distingué.", "%s: Certaines recherches devraient rester privées." } }
addon.localeData.frFR.generalTexts.OOM = { gruppe = { "Mes réserves de magie sont totalement épuisées !", "Une gorgée d'eau ne suffira pas." }, ziel = { "%s: Une gorgée d'eau ne suffira pas.", "%s: Mes réserves de magie sont totalement épuisées !" } }
addon.localeData.frFR.generalTexts.OPENFIRE = { gruppe = { "À mon signal ! Ouvrez le feu !", "Visez et tenez la ligne." }, ziel = { "%s: Visez et tenez la ligne.", "%s: À mon signal ! Ouvrez le feu !" } }
addon.localeData.frFR.generalTexts.PANIC = { gruppe = { "Cela ne faisait pas partie du plan !", "Pourquoi tout le monde court-il dans tous les sens ?" }, ziel = { "%s: Pourquoi tout le monde court-il dans tous les sens ?", "%s: Cela ne faisait pas partie du plan !" } }
addon.localeData.frFR.generalTexts.PARTY = { gruppe = { "Ce soir, l'aventure attendra dehors.", "La musique et les amis suffisent pour faire la fête." }, ziel = { "%s: La musique et les amis suffisent pour faire la fête.", "%s: Ce soir, l'aventure attendra dehors." } }
addon.localeData.frFR.generalTexts.PAT = { gruppe = { "Bien joué. Ce n'était pas facile.", "Parfois le courage mérite juste un peu de reconnaissance." }, ziel = { "%s: Parfois le courage mérite juste un peu de reconnaissance.", "%s: Bien joué. Ce n'était pas facile." } }
addon.localeData.frFR.generalTexts.PEER = { gruppe = { "Il y a quelque chose qui bouge là-bas.", "Je vais regarder de plus près avant de juger." }, ziel = { "%s: Je vais regarder de plus près avant de juger.", "%s: Il y a quelque chose qui bouge là-bas." } }
addon.localeData.frFR.generalTexts.PEST = { gruppe = { "Un peu d'agitation maintient tout le monde éveillé.", "Je devrais peut-être moins taquiner les autres." }, ziel = { "%s: Je devrais peut-être moins taquiner les autres.", "%s: Un peu d'agitation maintient tout le monde éveillé." } }
addon.localeData.frFR.generalTexts.PICK = { gruppe = { "Certaines choses ne cèdent qu'à la patience.", "Un geste habile évite bien des efforts." }, ziel = { "%s: Un geste habile évite bien des efforts.", "%s: Certaines choses ne cèdent qu'à la patience." } }
addon.localeData.frFR.generalTexts.PITY = { gruppe = { "Personne ne devrait subir cela.", "Ma compassion va à tous ceux qui en souffrent." }, ziel = { "%s: Ma compassion va à tous ceux qui en souffrent.", "%s: Personne ne devrait subir cela." } }
addon.localeData.frFR.generalTexts.PIZZA = { gruppe = { "Un repas chaud peut sauver une soirée.", "Qui veut une part doit le dire maintenant." }, ziel = { "%s: Qui veut une part doit le dire maintenant.", "%s: Un repas chaud peut sauver une soirée." } }
addon.localeData.frFR.generalTexts.PLEAD = { gruppe = { "Je t'en prie, laisse-moi finir.", "Il y a plus en jeu que tu ne le penses." }, ziel = { "%s: Il y a plus en jeu que tu ne le penses.", "%s: Je t'en prie, laisse-moi finir." } }
addon.localeData.frFR.generalTexts.POKE = { gruppe = { "Tu es toujours parmi les vivants ?", "Une petite incitation devrait suffire." }, ziel = { "%s: Une petite incitation devrait suffire.", "%s: Tu es toujours parmi les vivants ?" } }
addon.localeData.frFR.generalTexts.PONDER = { gruppe = { "Cela mérite une réflexion sérieuse.", "Toutes les réponses ne viennent pas immédiatement." }, ziel = { "%s: Toutes les réponses ne viennent pas immédiatement.", "%s: Cela mérite une réflexion sérieuse." } }
addon.localeData.frFR.generalTexts.POUNCE = { gruppe = { "Surprise ! À ton tour maintenant.", "Le meilleur plan commence parfois par un bond." }, ziel = { "%s: Le meilleur plan commence parfois par un bond.", "%s: Surprise ! À ton tour maintenant." } }
addon.localeData.frFR.generalTexts.PRAISE = { gruppe = { "Cela mérite des éloges sincères.", "Les grands actes n'ont pas besoin de grands discours." }, ziel = { "%s: Les grands actes n'ont pas besoin de grands discours.", "%s: Cela mérite des éloges sincères." } }
addon.localeData.frFR.generalTexts.PRAY = { gruppe = { "Qu'un peu de sagesse nous guide aujourd'hui.", "Même dans la tempête, l'espoir a sa place." }, ziel = { "%s: Même dans la tempête, l'espoir a sa place.", "%s: Qu'un peu de sagesse nous guide aujourd'hui." } }
addon.localeData.frFR.generalTexts.PUZZLED = { gruppe = { "Il manque encore une pièce à cette énigme.", "La réponse est probablement sous nos yeux." }, ziel = { "%s: La réponse est probablement sous nos yeux.", "%s: Il manque encore une pièce à cette énigme." } }
addon.localeData.frFR.generalTexts.QUESTION = { gruppe = { "Puis-je poser une question à ce sujet ?", "Une bonne question vaut la moitié d'une réponse." }, ziel = { "%s: Une bonne question vaut la moitié d'une réponse.", "%s: Puis-je poser une question à ce sujet ?" } }
